-- Migration v7.2 — Chinese and new electric brands now sold in Portugal
--
-- Jaecoo, Leapmotor, Xpeng, Zeekr, KGM, Ebro, Dongfeng and Voyah were missing from the
-- catalogue, so the monthly market snapshot never read their listings. Also new models
-- of brands we have (Omoda 7/9, BYD Dolphin G/Han/Tang, MG4 Urban, MG S5/S6/S9).
--
-- Per model: body type, the year it reached Portugal, one generation with the page it
-- was read on, and engines from the Portuguese price guide's technical sheets (Guia do
-- Automóvel, JATO data, read 2026-11-16; researched in
-- docs/agents-2026-11-14/ev_models_research.json, generated by gen_v72.py).
--
--   reliability_score   brand anchor (brand_reliability); a plug-in hybrid 0.2 below.
--                       Brands without published studies: 7.0, the middle of the scale.
--   maintenance         estimate by powertrain (EV 250, HEV 320, PHEV 380, petrol 360,
--                       diesel 420 EUR/year).
--   displacement        nominal for the stated litres (1.5 -> 1498 cc).
--   driving_character   editorial defaults by body type (EV: +1 comfort, +1 city) —
--                       not a road test; say so in the description.
--
-- New-car list prices go to seeds/new_car_list_prices.json (with source and date);
-- used prices come from the monthly snapshot once enough listings exist.
-- Not added: Lynk & Co 01 (no Portuguese importer), Zeekr 9X (not yet on sale).
--
-- Idempotent: every row is added only if missing.

BEGIN;

INSERT INTO brands (name, country, segment)
VALUES
    ('Jaecoo', 'China', 'generalista'),
    ('Leapmotor', 'China', 'generalista'),
    ('Xpeng', 'China', 'generalista'),
    ('Zeekr', 'China', 'premium'),
    ('KGM', 'Coreia do Sul', 'generalista'),
    ('Ebro', 'Espanha', 'generalista'),
    ('Dongfeng', 'China', 'generalista'),
    ('Voyah', 'China', 'premium')
ON CONFLICT (name) DO NOTHING;

INSERT INTO brand_reliability (brand_id, score, studies, sources, method, as_of)
SELECT b.id, 7.0, 0, '[]'::jsonb,
       'Sem estudos publicados para a marca: meio da escala (7,0) até haver dados.', DATE '2026-11-17'
FROM brands b
WHERE b.name IN ('Jaecoo', 'Leapmotor', 'Xpeng', 'Zeekr', 'KGM', 'Ebro', 'Dongfeng', 'Voyah')
  AND NOT EXISTS (SELECT 1 FROM brand_reliability r WHERE r.brand_id = b.id);

