       co2_emissions, reliability_score, maintenance_cost_year, year_from, year_to, plug_in, source, basis)
JOIN brands b ON b.name = v.brand JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE NOT EXISTS (SELECT 1 FROM engines e WHERE e.model_id = vm.id AND e.code = v.code);

COMMIT;
